const words={seller:['مركز التاجر','Seller center'],title:['الرصيد والاستقطاع','Balance & commission'],refresh:['تحديث','Refresh'],ruleTitle:['حصة الاستقطاع الأساسية','Base commission'],basis:['تُحسب على قيمة المنتجات بعد الخصم دون التوصيل. قواعد المنتجات الخاصة تظهر أدناه.','Calculated on products after discount, excluding delivery. Product-specific rules appear below.'],rulesTitle:['قواعد خاصة بالمنتجات','Product-specific rules'],history:['سجل الرصيد — آخر 100 حركة','Balance history — latest 100 entries'],adminTitle:['إعداد حصة الاستقطاع','Commission settings'],productId:['معرّف المنتج — فارغ للنسبة العامة','Product ID — blank for global rate'],rateLabel:['النسبة %','Percentage %'],fixedLabel:['رسم إضافي لكل قطعة بعملة المنتج (صفر دون رسم)','Additional fee per unit in product currency (zero for none)'],currencyLabel:['عملة قاعدة المنتج','Product rule currency'],reasonLabel:['سبب القاعدة، بما فيه العرض أو الخصم','Reason, including offer or discount'],saveRule:['حفظ القاعدة','Save rule'],futureOnly:['التغييرات للطلبات الجديدة فقط. تعديل النسبة لا يفعّل الشحن أو الاستقطاع.','Changes apply only to new orders. Changing a rate does not activate funding or charges.'],off:['الحجز والاستقطاع التلقائي متوقفان · إدخال الرصيد بواسطة الإدارة فقط','Automatic commission is disabled · admin-managed balance only'],on:['حجز الاستقطاع عند قبول الطلب','Commission reserved on order acceptance'],empty:['لا توجد حركات رصيد معتمدة بعد.','No approved balance transactions yet.'],noRules:['لا توجد رسوم خاصة محفوظة. تُستخدم النسبة العامة.','No saved overrides. The global rate applies.'],available:['متاح','Available'],reserved:['محجوز','Reserved'],ADMIN_REQUIRED:['هذه العملية مخصصة للإدارة المخوّلة.','This action requires an authorized administrator.'],RULE_INVALID:['تحقق من النسبة والعملة ومعرّف المنتج والرسم.','Check the rate, currency, product ID and fee.']};
Object.assign(words,{manualTitle:['إدارة الرصيد يدويًا','Manual balance administration'],chooseStore:['المتجر','Store'],actionLabel:['الإجراء','Action'],credit:['إضافة رصيد','Add credit'],debit:['خفض الرصيد المتاح','Decrease available balance'],freeze:['تجميد الحجز الجديد','Freeze new reservations'],unfreeze:['رفع التجميد','Unfreeze'],pause:['إيقاف الاستقطاع للجميع','Pause commission for all'],minorAmount:['المبلغ بعملة الحساب','Amount in account currency'],referenceLabel:['مرجع فريد للحركة','Unique transaction reference'],applyManual:['تنفيذ مع تسجيل السبب','Apply and record reason'],bankTitle:['بيانات الحساب البنكي والملاحظات','Bank account & notes'],bankName:['اسم البنك','Bank name'],beneficiary:['اسم المستفيد','Beneficiary'],bankAccount:['رقم الحساب','Account number'],last4:['آخر 4 أرقام للبطاقة فقط','Card last 4 digits only'],notes:['ملاحظات','Notes'],frozen:['الحجز الجديد مجمّد','New reservations frozen'],active:['الحساب غير مجمّد','Account not frozen'],BALANCE_INSUFFICIENT:['الرصيد المتاح لا يكفي؛ لا يمكن خفض المبلغ المحجوز.','Insufficient available balance; reserved funds cannot be deducted.'],FINANCE_INVALID:['تحقق من الحقول والمبلغ والمرجع.','Check the fields, amount and reference.'],REQUEST_CONFLICT:['مرجع العملية مستخدم ببيانات مختلفة.','This request is already used with different data.']});
