const w=window.BemoWorkspace.create(words,{onReady:()=>w.run(load),onClear:()=>{data=null;adminData=null;manualKey=null;manualSignature=null;$('manualAdmin').hidden=true;$('ruleForm').reset();$('financeState').textContent='';$('manualForm').reset();$('bankForm').reset();$('adminStore').replaceChildren();$('adminHistory').replaceChildren();$('adminBalance').textContent='';for(const id of ['balances','transactions','rules'])w.$(id).replaceChildren();w.$('adminRules').hidden=true;w.$('baseRate').textContent='—';},onLanguage:()=>{if(data)render(true);if(adminData)renderAdmin(true);}}),$=w.$,n=w.node;
async function load(req){data=await req('bemo_balance_workspace');if(data.can_configure){adminData=await req('bemo_finance_admin_workspace',{target_store:$('adminStore').value||null});}render();if(adminData)renderAdmin();}
function render(keepDraft=false){$('baseRate').textContent=(data.basis_points/100)+'%';$('financeState').textContent=w.t(data.enabled?'on':'off')+(data.frozen?' · '+w.t('frozen'):'');$('balances').replaceChildren();if(!data.balances.length)$('balances').append(n('p',w.t('empty'),'workspace-empty'));for(const b of data.balances)for(const key of ['available','reserved']){const card=n('div',undefined,'metric');card.append(n('span',w.t(key)),n('strong',window.BemoLive.money(b[key+'_minor'],b.currency,w.lang())));$('balances').append(card);}
 $('rules').replaceChildren();if(!data.rules.length)$('rules').append(n('p',w.t('noRules'),'live-note'));for(const r of data.rules){const row=n('div',undefined,'recent-order');row.append(n('span',r.product_id),n('strong',(r.basis_points/100)+'% + '+window.BemoLive.money(r.fixed_minor,r.currency,w.lang())),n('span',r.note));$('rules').append(row);}
 $('transactions').replaceChildren();if(!data.transactions.length)$('transactions').append(n('p',w.t('empty'),'workspace-empty'));for(const t of data.transactions){const row=n('div',undefined,'recent-order');row.append(n('span',(kinds[t.kind]||[t.kind,t.kind])[w.lang()==='ar'?0:1]),n('strong',window.BemoLive.money(t.available_delta,t.currency,w.lang())),n('time',new Intl.DateTimeFormat(w.lang(),{dateStyle:'medium',timeStyle:'short'}).format(new Date(t.created_at))));if(t.suborder_id){const a=n('a','#'+t.suborder_id.slice(0,8));a.href=w.url('orders.html',{view:'seller',id:t.suborder_id});row.append(a);}$('transactions').append(row);}
 $('adminRules').hidden=!data.can_configure;if(!keepDraft)$('rate').value=data.basis_points/100;
}
function renderAdmin(keepDraft=false){const selected=$('adminStore').value;$('manualAdmin').hidden=false;$('adminStore').replaceChildren(n('option',w.lang()==='ar'?'اختر متجرًا':'Choose a store'));for(const s of adminData.stores){const o=n('option',s.title+' · '+s.slug);o.value=s.id;$('adminStore').append(o);}$('adminStore').children[0].value='';$('adminStore').value=selected;const a=adminData.account;$('adminBalance').textContent=w.t(a.frozen?'frozen':'active')+' · '+adminData.balances.map(b=>w.t('available')+': '+window.BemoLive.money(b.available_minor,b.currency,w.lang())+' / '+w.t('reserved')+': '+window.BemoLive.money(b.reserved_minor,b.currency,w.lang())).join(' · ');if(!keepDraft)for(const [id,key]of [['bankName','bank_name'],['beneficiary','beneficiary'],['bankAccount','account_number'],['iban','iban'],['last4','card_last4'],['bankNotes','notes']])$(id).value=a.bank[key]||'';$('adminHistory').replaceChildren();for(const t of adminData.history){const row=n('p',(kinds[t.kind]||[t.kind,t.kind])[w.lang()==='ar'?0:1]+' · '+window.BemoLive.money(t.available_delta,t.currency,w.lang())+' · '+t.reference+' · '+t.reason);$('adminHistory').append(row);}}
function manual(action,payload,reason){const store_id=$('adminStore').value||null;if(action!=='PAUSE'&&!store_id)return;const signature=JSON.stringify([store_id,action,payload,reason]);if(manualSignature!==signature){manualSignature=signature;manualKey=crypto.randomUUID();}const args={store_id,action,payload,reason,request_id:manualKey};w.run(async req=>{await req('bemo_finance_admin_action',args);manualKey=null;manualSignature=null;await load(req);},'saving');}
$('adminStore').addEventListener('change',()=>w.run(load));$('manualForm').addEventListener('submit',e=>{e.preventDefault();try{const action=$('manualAction').value,payload=['CREDIT','ADJUST_DOWN'].includes(action)?{amount_minor:window.BemoLive.priceMinor($('manualAmount').value,$('manualCurrency').value.trim().toUpperCase()),currency:$('manualCurrency').value.trim().toUpperCase(),reference:$('manualReference').value.trim()}:{};manual(action,payload,$('manualReason').value.trim());}catch(_){$('error').hidden=false;$('error').textContent=w.t('FINANCE_INVALID');}});$('bankForm').addEventListener('submit',e=>{e.preventDefault();manual('BANK',{bank_name:$('bankName').value.trim(),beneficiary:$('beneficiary').value.trim(),account_number:$('bankAccount').value.trim(),iban:$('iban').value.trim(),card_last4:$('last4').value.trim(),notes:$('bankNotes').value.trim(),version:adminData.account.version},$('bankReason').value.trim());});
